import CheckRoundedIcon from '@mui/icons-material/CheckRounded';
import RemoveRoundedIcon from '@mui/icons-material/RemoveRounded';
import Box from '@mui/material/Box';
import { buttonBaseClasses } from '@mui/material/ButtonBase';
import Checkbox, {
  checkboxClasses,
  type CheckboxProps,
} from '@mui/material/Checkbox';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import type { SxProps, Theme } from '@mui/material/styles';
import { mergeSlotProps } from '@mui/material/utils';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef, type Ref } from 'react';
import { svTokens } from '../../theme/tokens';

export interface SvCheckboxProps extends CheckboxProps {
  /** Replaces the default check mark when the checkbox is selected. */
  selectionNumber?: number | string | undefined;
}

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvCheckbox: SvCheckboxProps;
  }
  interface Components {
    SvCheckbox?:
      { defaultProps?: Partial<SvCheckboxProps> | undefined } | undefined;
  }
}

const sizes = { small: 16, medium: 20, large: 24 } as const;

const iconSx: SxProps<Theme> = {
  width: 'var(--SvCheckbox-size)',
  height: 'var(--SvCheckbox-size)',
  borderRadius: '4px',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  flexShrink: 0,
  boxSizing: 'border-box',
};

const emptyIconSx: SxProps<Theme> = {
  border: '2px solid var(--SvCheckbox-stroke)',
  [`.${checkboxClasses.root}.${checkboxClasses.disabled} &`]: { opacity: 0.4 },
};

const filledIconSx: SxProps<Theme> = {
  backgroundColor: 'var(--SvCheckbox-fill)',
  color: 'var(--SvCheckbox-foreground)',
  [`.${checkboxClasses.root}.${checkboxClasses.disabled} &`]: { opacity: 0.5 },
};

export const SvCheckbox = forwardRef<HTMLSpanElement, SvCheckboxProps>(
  function SvCheckbox(inProps, ref) {
    const muiDefaults = useDefaultProps<SvCheckboxProps>({
      props: {},
      name: 'MuiCheckbox',
    });
    const svDefaults = useDefaultProps<SvCheckboxProps>({
      props: {},
      name: 'SvCheckbox',
    });
    const svProps = useDefaultProps({ props: inProps, name: 'SvCheckbox' });
    const resolved = useDefaultProps({ props: svProps, name: 'MuiCheckbox' });
    const {
      selectionNumber,
      className,
      sx: _resolvedSx,
      slotProps,
      icon,
      checkedIcon,
      indeterminateIcon,
      size = 'small',
      color = 'primary',
      disableRipple = true,
      ...props
    } = resolved;
    const sizePx = sizes[size as keyof typeof sizes] ?? sizes.small;
    const controlSx: SxProps<Theme> = (theme) => {
      const palette = (theme.vars ?? theme).palette;
      const swatch = palette[color as keyof typeof palette];
      const paletteColor =
        swatch && typeof swatch === 'object' && 'main' in swatch
          ? (swatch.main as string)
          : palette.text.secondary;
      return {
        padding: '4px',
        minWidth: 24,
        minHeight: 24,
        '--SvCheckbox-size': `${sizePx}px`,
        '--SvCheckbox-accent': svTokens(theme).accent,
        '--SvCheckbox-stroke': svTokens(theme).stroke,
        '--SvCheckbox-foreground': '#fff',
        '--SvCheckbox-fill':
          color === 'primary'
            ? 'var(--SvCheckbox-accent)'
            : color === 'default'
              ? palette.text.secondary
              : paletteColor,
        [`&.${buttonBaseClasses.focusVisible}`]: {
          outline: `2px solid ${svTokens(theme).focus}`,
          outlineOffset: 2,
        },
      };
    };
    const rootSx = mergeSx(
      controlSx,
      muiDefaults.sx,
      svDefaults.sx,
      inProps.sx
    );

    const defaultIcon = (
      <Box
        component="span"
        aria-hidden="true"
        sx={mergeSx(iconSx, emptyIconSx)}
      />
    );
    const defaultCheckedIcon = (
      <Box
        component="span"
        aria-hidden="true"
        sx={mergeSx(iconSx, filledIconSx)}
      >
        {selectionNumber == null ? (
          <CheckRoundedIcon sx={{ fontSize: 'var(--SvCheckbox-size)' }} />
        ) : (
          <Box
            component="span"
            className="SvCheckbox-number"
            sx={{
              display: 'block',
              maxWidth: '100%',
              overflow: 'hidden',
              whiteSpace: 'nowrap',
              fontFamily: 'Inter, sans-serif',
              fontSize: 12,
              fontWeight: 400,
              lineHeight: '16px',
              textAlign: 'center',
            }}
          >
            {selectionNumber}
          </Box>
        )}
      </Box>
    );
    const defaultIndeterminateIcon = (
      <Box
        component="span"
        aria-hidden="true"
        sx={mergeSx(iconSx, filledIconSx)}
      >
        <RemoveRoundedIcon sx={{ fontSize: 'var(--SvCheckbox-size)' }} />
      </Box>
    );

    return (
      <Checkbox
        {...props}
        size={size}
        color={color}
        disableRipple={disableRipple}
        icon={icon ?? defaultIcon}
        checkedIcon={checkedIcon ?? defaultCheckedIcon}
        indeterminateIcon={indeterminateIcon ?? defaultIndeterminateIcon}
        // MUI types the ButtonBase ref as a button, but Checkbox renders a span.
        ref={ref as Ref<HTMLButtonElement>}
        className={clsx('SvCheckbox-root', className)}
        sx={rootSx}
        slotProps={{
          ...slotProps,
          root: mergeSlotProps(slotProps?.root, { sx: rootSx }),
        }}
      />
    );
  }
);
